```python
def sum_of_proper_divisors(n):
    divisors = [1]
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return sum(divisors)

def amicable_numbers_sum(limit):
    amicable_pairs = set()
    for i in range(2, limit + 1):
        sum_divisors_i = sum_of_proper_divisors(i)
        sum_divisors_sum_divisors_i = sum_of_proper_divisors(sum_divisors_i)
        if sum_divisors_sum_divisors_i == i and sum_divisors_i != i:
            amicable_pairs.add((min(i, sum_divisors_i), max(i, sum_divisors_i)))
    return sum(pair[0] for pair in amicable_pairs if pair[0] <= limit)

# Test cases
