def count_bidirectional(pairs):
    bidirectional_pairs = set()
    seen = {}

    for pair in pairs:
        reversed_pair = (pair[1], pair[0])

        if pair == reversed_pair:
            continue

        if reversed_pair in seen:
            if pair == seen[reversed_pair]:
                bidirectional_pairs.add(pair)
        else:
            seen[pair] = reversed_pair
            seen[reversed_pair] = pair

    return len(bidirectional_pairs)

